<style lang="scss" src="./update-summary-modal.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import {
  destroyModalRootContent,
  ensureModalRoot
} from "../../util/ensure-modal-root";
import ScrollView from "../scroll-view/scroll-view";
import { MountingPortal } from "portal-vue";
import IconButton from "../icon-button/icon-button.vue";
import Icon from "../icon/icon.vue";
import { IconShape } from "../icon/icon.constants";
import PageIndicator from "../page-indicator/page-indicator";

@Component({
  components: {
    ScrollView,
    MountingPortal,
    IconButton,
    Icon,
    PageIndicator
  }
})
export default class UpdateSummaryModal extends Vue {
  @Prop({ type: String }) image;
  /** The blurb of text for the summary to render */
  @Prop({ type: String }) summary;
  /** The title of the summary */
  @Prop({ type: String }) title;
  /** Date the summary was posted */
  @Prop({ type: Date }) date;
  /** When provided, the previous button will be available */
  @Prop({ type: Boolean }) previous;
  /** When provided, the next button will be available */
  @Prop({ type: Boolean }) next;
  /** Indicates the current page */
  @Prop({
    type: Number
  })
  currentPage;
  /** Indicates the total page number */
  @Prop({
    type: Number
  })
  totalPageNumber;

  /**
   * This is the root modal element the menu resides in to render floating above
   * all the other elements in the DOM.
   */
  modalRoot = null;

  // Enums
  IconShape = IconShape;

  beforeMount() {
    // HACK: MountingPortal spawns mass duplicates. So as Thanos once said:
    //       Fine. I'll do it myself
    destroyModalRootContent("Menu");
    this.modalRoot = ensureModalRoot();

    if (!this.modalRoot) {
      console.warn("Could not establish modal root for floating componentry");
      return;
    }

    window.addEventListener("resize", this.handleResize);
  }

  beforeDestroy() {
    window.removeEventListener("resize", this.handleResize);
  }

  /**
   * HACKY HACKS: Due to vue portal having it's own set of issues and we handle
   * its DOM disposal manually, this causes certain scenarios to throw errors
   * from the MountingPortal component. So, we just absorb those issues here for
   * now until better solutions can be discovered or Vue3 is used with better
   * native made portals.
   */
  errorCaptured(err, vm, info) {
    if (info === "beforeDestroy hook") {
      return false;
    }
  }

  get dateText() {
    if (this.date) {
      const year = new Intl.DateTimeFormat("en", { year: "numeric" }).format(
        this.date
      );
      const month = new Intl.DateTimeFormat("en", { month: "long" }).format(
        this.date
      );
      const day = new Intl.DateTimeFormat("en", { day: "2-digit" }).format(
        this.date
      );
      return `${month} ${day}, ${year}`;
    }

    return "";
  }

  get modalRootId() {
    return `#${this.modalRoot.id}`;
  }

  get containerStyle() {
    return {
      height: `${window.innerHeight}px`
    };
  }

  get imageStyle() {
    return {
      backgroundImage: `url(${this.image})`
    };
  }

  handleCloseOutside(e) {
    if (e.target !== this.$refs.container) return;
    this.$emit("close");
    e.stopPropagation();
    e.preventDefault();
  }

  handleClose() {
    this.$emit("close");
  }

  handleResize() {
    this.$forceUpdate();
  }
}
</script>

<template>
  <MountingPortal :mountTo="modalRootId" append>
    <div
      class="UpdateSummaryModal"
      :style="containerStyle"
      ref="container"
      @click="handleCloseOutside"
    >
      <div class="UpdateSummaryModal__Content">
        <div class="UpdateSummaryModal__Left">
          <div
            v-if="image"
            class="UpdateSummaryModal__Image"
            :style="imageStyle"
          />
          <div class="UpdateSummaryModal__Head">
            <div class="UpdateSummaryModal__Date">
              <span class="UpdateSummaryModal__Text">{{ dateText }}</span>
            </div>
            <div class="UpdateSummaryModal__Title">
              <span class="UpdateSummaryModal__Text">{{ title }}</span>
            </div>
          </div>
          <Icon
            class="UpdateSummaryModal__Close"
            :shape="IconShape.CLOSE"
            :size="16"
            @click="handleClose"
          />
        </div>
        <div class="UpdateSummaryModal__Right">
          <ScrollView>
            <div ref="summary" class="UpdateSummaryModal__Summary">
              <span v-html="summary"></span>
            </div>
          </ScrollView>
        </div>
        <div class="UpdateSummaryModal__Actions">
          <div class="UpdateSummaryModal__Button">
            <IconButton
              v-if="previous"
              :shape="IconShape.LEFT"
              @click="$emit('previous')"
            />
          </div>
          <PageIndicator
            :currentPage="currentPage"
            :totalPageNumber="totalPageNumber"
          />
          <div class="UpdateSummaryModal__Button">
            <IconButton
              v-if="next"
              :shape="IconShape.RIGHT"
              @click="$emit('next')"
            />
          </div>
        </div>
      </div>
    </div>
  </MountingPortal>
</template>
